(1238, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_download_fbs_invoices', '下载 FBS 发票', 'This API allows you to download FBS invoices. To use this API, the client must first call v2.order.generate_fbs_invoices to create a new shipping document task, followed by calling v2.order.get_fbs_invoices_result to check the task status. The document can only be downloaded once the task status is "READY."', '下载 FBS 发票。', 'POST', '/api/v2/order/download_fbs_invoices', 1, 0),
(1239, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_download_invoice_doc', '下载发票文件', 'This endpoint only for PH and BR local seller. Seller can download the invoice uploaded before through this endpoint.', '下载发票文件。', 'GET', '/api/v2/order/download_invoice_doc', 1, 0),
(1240, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_generate_fbs_invoices', '生成 FBS 发票下载任务', 'This API creates a task to download a specific tax document (e.g., sales invoice, remessa invoice) for the seller''s account, available only after the document is issued by the system as part of the Fulfilled by Shopee (FBS) process. The workflow is as follows: (1) v2.order.generate_fbs_invoices; (2) v2.order.get_fbs_invoices_result; (3) v2.order.download_fbs_invoices. Please note: The download link for the document will expire 30 minutes after being generated.', '生成 FBS 发票下载任务。', 'POST', '/api/v2/order/generate_fbs_invoices', 1, 0),
