(1243, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_buyer_invoice_info', '查询买家发票信息', 'API to obtain buyer submitted invoice info for VN, TH and PH local sellers only.', '查询买家发票信息。', 'POST', '/api/v2/order/get_buyer_invoice_info', 1, 0),
(1244, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_estimate_cancel_value', '预估取消订单退款金额', 'Returns the estimated refund value for a partial order cancellation given the specified items to cancel.', '预估取消订单退款金额。', 'POST', '/api/v2/order/get_estimate_cancel_value', 1, 0),
(1245, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_fbs_invoices_result', '查询 FBS 发票下载结果', 'This API allows you to consult the status of a previously requested batch download for FBS tax documents.', '查询 FBS 发票下载结果。', 'POST', '/api/v2/order/get_fbs_invoices_result', 1, 0),
(1246, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_order_detail', '查询订单详情', 'Use this api to get order detail.', '查询订单详情。', 'GET', '/api/v2/order/get_order_detail', 1, 0),
(1247, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_order_list', '查询订单列表', 'Use this api to search orders. You may also filter them by status, if needed.', '查询订单列表。', 'GET', '/api/v2/order/get_order_list', 1, 0),
(1248, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_package_detail', '查询包裹详情', 'Use this api to get package detail.', '查询包裹详情。', 'GET', '/api/v2/order/get_package_detail', 1, 0),
(1249, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_pending_buyer_invoice_order_list', '查询待上传发票的订单列表', 'This endpoint only for PH and BR local sellers only. This API is used for seller to retrieve a list of order IDs that are pending invoice upload.', '查询待上传发票的订单列表。', 'GET', '/api/v2/order/get_pending_buyer_invoice_order_list', 1, 0),
(1250, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_shipment_list', '查询待发货订单列表', 'Use this api to get order list which order_status is READY_TO_SHIP or RETRY_SHIP to start process the whole shipping progress.', '查询待发货订单列表。', 'GET', '/api/v2/order/get_shipment_list', 1, 0),
(1251, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_get_warehouse_filter_config', '查询仓库筛选配置', 'For multi-warehouse shops, return all warehouses with packages that have not been SHIPPED including product_location_id and address_id. Compared to v2.shop.get_warehouse_detail, it covers some edge cases like warehouse that have been unlinked but still retain packages that have not been SHIPPED, and does not cover some cases like single warehouse with default product_location_id and FBS shop.', '查询仓库筛选配置。', 'GET', '/api/v2/order/get_warehouse_filter_config', 1, 0),
(1252, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_handle_buyer_cancellation', '处理买家取消申请', 'Use this api to handle buyer''s cancellation application.', '处理买家取消申请。', 'POST', '/api/v2/order/handle_buyer_cancellation', 1, 0),
(1253, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_handle_prescription_check', '审核处方', 'Use this API to approve or reject a prescription', '审核处方。', 'POST', '/api/v2/order/handle_prescription_check', 1, 0),
(1254, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_search_package_list', '搜索待发货包裹', 'Use this API to search the list of packages that have not been SHIPPED to proceed arranging shipment, and it supports various filters and sort fields.', '搜索待发货包裹。', 'POST', '/api/v2/order/search_package_list', 1, 0),
(1255, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_set_note', '设置订单备注', 'Use this api to set note for an order.', '设置订单备注。', 'POST', '/api/v2/order/set_note', 1, 0),
(1256, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_split_order', '拆分订单', 'Use this api to split an order into multiple packages. Orders that include installation services cannot be split by quantity.', '拆分订单。', 'POST', '/api/v2/order/split_order', 1, 0),
(1257, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_unsplit_order', '撤销订单拆分', 'Use this ai to undo split of order. After undo split, the order will have only one package. It can only be used when order status still at READY_TO_SHIP.', '撤销订单拆分。', 'POST', '/api/v2/order/unsplit_order', 1, 0),
(1258, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'order', '订单', 'v2_order_upload_invoice_doc', '上传发票文件', 'This endpoint is for PH and BR local seller. Upload the invoice document', '上传发票文件。', 'POST', '/api/v2/order/upload_invoice_doc', 1, 0),
(1259, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_batch_ship_order', '批量安排订单发货', 'Use this api to batch initiate logistics including arrange pickup, dropoff or shipment for non-integrated logistic channels. Should call v2.logistics.get_shipping_parameter to fetch all required param first. It''s recommended to initiate logistics one hour after the orders were placed since there is one-hour window buyer can cancel any order without request to seller.Only channel 90003 - Padrão in Brazil has the permission of this API.', '批量安排订单发货。', 'POST', '/api/v2/logistics/batch_ship_order', 1, 0),
(1260, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_batch_update_tpf_warehouse_tracking_status', '批量更新第三方仓跟踪状态', 'For CB orders that fulfilled by 3PF, support 3PF Warehouse Vendors to update the tpf_tracking_status when 3PF warehouse receive the order and complete the outbound of the package. CB orders that fulfilled by 3PF： v2.shop.get_shop_info - shop_fulfillment_flag in {Pure - 3PF Shop,PFF - 3PF Shop,LFF Hybrid Shop} And v2.order.get_order_detail - fulfillment_flag = fulfilled_by_local_seller', '批量更新第三方仓跟踪状态。', 'POST', '/api/v2/logistics/batch_update_tpf_warehouse_tracking_status', 1, 0),
(1261, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_check_polygon_update_status', '查询配送区域文件更新状态', 'Only available for Brazil sellers. Use this API to check the status of polygon file uploaded for BR Entrega Turbo channel (Channel ID: 90026) by querying the task_id returned via the v2.logistics.upload_serviceable_polygon.', '查询配送区域文件更新状态。', 'POST', '/api/v2/logistics/check_polygon_update_status', 1, 0),
(1262, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_create_booking_shipping_document', '创建预订面单任务', 'Use this api to create shipping document task for each booking and this API is only available after retrieving the tracking number.', '创建预订面单任务。', 'POST', '/api/v2/logistics/create_booking_shipping_document', 1, 0),
(1263, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_create_shipping_document_job', '创建面单批量任务', 'This API creates a shipping document job for selected documents. The system receives requests and returns a job ID along with success and failure details.', '创建面单批量任务。', 'POST', '/api/v2/logistics/create_shipping_document_job', 1, 0),
(1264, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_create_shipping_document', '创建面单任务', 'Use this api to create shipping document task for each order or package and this API is only available after retrieving the tracking number.', '创建面单任务。', 'POST', '/api/v2/logistics/create_shipping_document', 1, 0),
(1265, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_delete_address', '删除发货地址', 'Use this api to delete address.', '删除发货地址。', 'POST', '/api/v2/logistics/delete_address', 1, 0),
(1266, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_delete_special_operating_hour', '删除特殊营业时间', 'This API is used to delete a specific special operating hour for a seller. This API allows sellers to manage their operating hours by removing any special operating hours that are no longer needed. To use this API, the name of the special operating hour to be deleted should be obtained from the v2.logistics.get_operating_hours API.', '删除特殊营业时间。', 'POST', '/api/v2/logistics/delete_special_operating_hour', 1, 0),
(1267, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_download_booking_shipping_document', '下载预订面单', 'Use this api to download shipping_document. You have to call v2.logistics.create_booking_shipping_document to create a new shipping document task first and call v2.logistics.get_booking_shipping_document_result to get the task status second. If the task is READY, you can download this shipping document.', '下载预订面单。', 'POST', '/api/v2/logistics/download_booking_shipping_document', 1, 0),
(1268, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_download_shipping_document_job', '下载面单批量任务文件', 'This API allows users to download the shipping document associated with a specific job ID. It checks the job status before proceeding with the download.', '下载面单批量任务文件。', 'POST', '/api/v2/logistics/download_shipping_document_job', 1, 0),
(1269, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_download_shipping_document', '下载面单', 'Use this api to download shipping_document. You have to call v2.logistics.create_shipping_document to create a new shipping document task first and call v2.logistics.get_shipping_document_resut to get the task status second. If the task is READY, you can download this shipping document.', '下载面单。', 'POST', '/api/v2/logistics/download_shipping_document', 1, 0),
(1270, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_download_to_label', '下载 TO 标签', 'Use the API to download the TO label that should be attached to the carton before drop-off at the warehouse (Only for TW channel_id:30029).', '下载 TO 标签。', 'POST', '/api/v2/logistics/download_to_label', 1, 0),
(1271, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_address_list', '查询揽收地址列表', 'For integrated logistics channel, use this call to get pickup address for pickup mode order.', '查询揽收地址列表。', 'GET', '/api/v2/logistics/get_address_list', 1, 0),
(1272, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_booking_shipping_document_data_info', '查询预订面单数据', 'Use this api to fetch the logistics information of a booking these info can be used for airwaybill printing. Dedicated for crossborder SLS order airwaybill. May not be applicable for local channel airwaybill. Besides, this api supports returning personal info as images.', '查询预订面单数据。', 'POST', '/api/v2/logistics/get_booking_shipping_document_data_info', 1, 0),
(1273, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_booking_shipping_document_parameter', '查询预订面单参数', 'Use this api to get the selectable shipping_document_type and suggested shipping_document_type.', '查询预订面单参数。', 'POST', '/api/v2/logistics/get_booking_shipping_document_parameter', 1, 0),
(1274, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_booking_shipping_document_result', '查询预订面单任务结果', 'Use this api to retrieve the status of the shipping document task. Document will be available for download only after the status change to ''READY''.', '查询预订面单任务结果。', 'POST', '/api/v2/logistics/get_booking_shipping_document_result', 1, 0),
(1275, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_booking_shipping_parameter', '查询预订发货参数', 'Use this api to get the parameter "info_needed" from the response to check if the booking has pickup or dropoff. This api will also return the addresses and pickup time id options for the pickup method. For dropoff, it can return branch id, sender real name etc, depending on the 3PL requirements.', '查询预订发货参数。', 'GET', '/api/v2/logistics/get_booking_shipping_parameter', 1, 0),
(1276, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_booking_tracking_info', '查询预订物流轨迹', 'Use this api to get the logistics tracking information of a booking.', '查询预订物流轨迹。', 'GET', '/api/v2/logistics/get_booking_tracking_info', 1, 0),
(1277, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_booking_tracking_number', '查询预订运单号', 'After arranging shipment (v2.logistics.ship_booking) for the integrated channel, use this api to get the tracking_number, which is a required parameter for creating shipping labels. The api response can return tracking_number empty, since this info is dependent from the 3PL, due to this it is allowed to keep calling the api within 5 minutes interval, until the tracking_number is returned.', '查询预订运单号。', 'GET', '/api/v2/logistics/get_booking_tracking_number', 1, 0),
(1278, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_channel_list', '查询物流渠道列表', 'Use this api to get all supported logistic channels.', '查询物流渠道列表。', 'GET', '/api/v2/logistics/get_channel_list', 1, 0),
(1279, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_mart_packaging_info', '查询 Mart 包装费设置', '[Only for ID mart seller] The API allows sellers to retrieve their current packaging fee settings.', '查询 Mart 包装费设置。', 'GET', '/api/v2/logistics/get_mart_packaging_info', 1, 0),
(1280, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_mass_shipping_parameter', '查询批量发货参数', 'Use this api to check if package support pickup, dropoff, non-integrated. For pickup, return address and pickup time id options. For dropoff, return branch id, sender real name, etc. Can batch request for packages under same product_location_id and logistics_channel_id. [Please call it when packages meet: 1) fulfillment status is LOGISTICS_READY; or 2) fulfillment status is LOGISTICS_PICKUP_RETRY; or 3) fulfillment status is LOGISTICS_REQUEST_CREATED and meet Instant Order Reschedule conditions]', '查询批量发货参数。', 'POST', '/api/v2/logistics/get_mass_shipping_parameter', 1, 0),
(1281, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_mass_tracking_number', '批量查询运单号', 'After arranging shipment (v2.logistics.mass_ship_order) for the integrated channel, use this api to get the tracking_number, which is a required parameter for creating shipping labels. The api response can return tracking_number empty, since this info is dependent from the 3PL, due to this it is allowed to keep calling the api within 5 minutes interval, until the tracking_number is returned.', '批量查询运单号。', 'POST', '/api/v2/logistics/get_mass_tracking_number', 1, 0),
(1282, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_operating_hour_restrictions', '查询营业时间限制', 'This API is designed to retrieve all restrictions related to inputting operating hours for the v2.logistics.update_operating_hours function. This API ensures that user are aware of any limitations or conditions that may affect their operating hours.', '查询营业时间限制。', 'GET', '/api/v2/logistics/get_operating_hour_restrictions', 1, 0),
(1283, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_operating_hours', '查询营业时间', 'This API is utilized to retrieve the existing operating hours of sellers including Pickup Operating Hours, Special Hours, Instant Operating Hours, and Shop Collection Operating Hours.', '查询营业时间。', 'GET', '/api/v2/logistics/get_operating_hours', 1, 0),
(1284, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_pause_status', '查询物流渠道暂停状态', 'This API returns the pause status of logistics channels under the shop. Pausing allows the shop to temporarily prevent buyers from placing orders through specific logistics channels. The response includes whether a pause is currently active, the pause end time (if active), and the remaining daily pause quota in seconds (if inactive). Sellers need to refer to the support_pause field in v2.logistics.get_channel_list response to determine which channels are actually paused.', '查询物流渠道暂停状态。', 'GET', '/api/v2/logistics/get_pause_status', 1, 0),
(1285, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_shipping_document_data_info', '查询面单数据', 'Use this api to fetch the logistics information of an order, these info can be used for self-design AWB printing. Besides, this api supports returning personal info as images.', '查询面单数据。', 'POST', '/api/v2/logistics/get_shipping_document_data_info', 1, 0),
(1286, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_shipping_document_job_status', '查询面单批量任务状态', 'This API retrieves the status of a shipping document job using the job ID provided.', '查询面单批量任务状态。', 'POST', '/api/v2/logistics/get_shipping_document_job_status', 1, 0),
(1287, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_shipping_document_parameter', '查询面单参数', 'Use this api to get the selectable shipping_document_type and suggested shipping_document_type.', '查询面单参数。', 'POST', '/api/v2/logistics/get_shipping_document_parameter', 1, 0),
(1288, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_shipping_document_result', '查询面单任务结果', 'Use this api to retrieve the status of the shipping document task. Document will be available for download only after the status change to ''READY''.', '查询面单任务结果。', 'POST', '/api/v2/logistics/get_shipping_document_result', 1, 0),
(1289, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_shipping_parameter', '查询发货参数', 'Use this api to check if the package support pickup, dropoff, or non-integrated method. For pickup, will return addresses and pickup time id options. For dropoff, will return branch id, sender real name etc, depending on 3PL requirements. [Please call this API when packages meet: 1) fulfillment status is LOGISTICS_READY; or 2) fulfillment status is LOGISTICS_PICKUP_RETRY; or 3) fulfillment status is LOGISTICS_REQUEST_CREATED and meet Instant Order Reschedule Pickup conditions]', '查询发货参数。', 'GET', '/api/v2/logistics/get_shipping_parameter', 1, 0),
(1290, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_tracking_info', '查询物流轨迹', 'Use this api to get the logistics tracking information of an order.', '查询物流轨迹。', 'GET', '/api/v2/logistics/get_tracking_info', 1, 0),
(1291, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_get_tracking_number', '查询运单号', 'After arranging shipment (v2.logistics.ship_order) for the integrated channel, use this api to get the tracking_number, which is a required parameter for creating shipping labels. The api response can return tracking_number empty, since this info is dependent from the 3PL, due to this it is allowed to keep calling the api within 5 minutes interval, until the tracking_number is returned.', '查询运单号。', 'GET', '/api/v2/logistics/get_tracking_number', 1, 0),
(1292, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_mass_ship_order', '批量安排包裹发货', 'Use this api to initiate logistics including arrange pickup, dropoff or shipment for non-integrated logistic channels. Should call v2.logistics.get_mass_shipping_parameter to fetch all required params first. It''s recommended to initiate logistics one hour after the orders were placed since there is one-hour window buyer can cancel any order without request to seller. The API can only batch arrange shipment for multiple packages under the same product_location_id and same logistics_channel_id.', '批量安排包裹发货。', 'POST', '/api/v2/logistics/mass_ship_order', 1, 0),
(1293, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_set_address_config', '设置发货地址配置', 'Use this API to set address config of your shop.', '设置发货地址配置。', 'POST', '/api/v2/logistics/set_address_config', 1, 0),
(1294, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_set_mart_packaging_info', '设置 Mart 包装费', '[Only for ID mart seller] This API allows sellers to set up their packaging fee info. Through this API, sellers can enable or disable packaging fees, and if enabled, specify the dimensions of the packaging and the associated fee. This ensures that sellers can configure their shipping costs accurately based on their packaging requirements.', '设置 Mart 包装费。', 'POST', '/api/v2/logistics/set_mart_packaging_info', 1, 0),
(1295, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_set_pause_status', '设置物流渠道暂停状态', 'Use this API to set the pause status of logistics channels under the shop. Pausing allows the shop to temporarily prevent buyers from placing orders through specific logistics channels. The response includes whether a pause is currently active, the pause end time (if active), and the remaining daily pause quota in seconds (if inactive). Note: The pause may take a few moments to take effect. Please check for any additional orders that may still be placed during this window.', '设置物流渠道暂停状态。', 'POST', '/api/v2/logistics/set_pause_status', 1, 0),
(1296, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_ship_booking', '安排预订发货', 'Use this api to initiate logistics including arrange pickup, dropoff. Should call v2.logistics.get_booking_shipping_parameter to fetch all required param first.', '安排预订发货。', 'POST', '/api/v2/logistics/ship_booking', 1, 0),
(1297, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_ship_order', '安排订单发货', 'Use this api to initiate logistics including arrange pickup, dropoff or shipment for non-integrated logistic channels. Should call v2.logistics.get_shipping_parameter to fetch all required param first. It''s recommended to initiate logistics one hour after the orders were placed.', '安排订单发货。', 'POST', '/api/v2/logistics/ship_order', 1, 0),
(1298, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_update_address', '更新发货地址', 'Use this API to update the address of a shop.', '更新发货地址。', 'POST', '/api/v2/logistics/update_address', 1, 0),
(1299, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_update_channel', '更新物流渠道配置', 'Use this api to update shop level logistics channel''s configuration.', '更新物流渠道配置。', 'POST', '/api/v2/logistics/update_channel', 1, 0),
(1300, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_update_operating_hours', '更新营业时间', 'This API is designed to allow sellers to update their operating hours. It is essential that the values provided in this API align with the restrictions retrieved from the v2.logistics.get_operating_hour_restrictions API to ensure compliance with platform requirements. This API uses overwriting updates, when updating pickup operating hours, still need to include all parts even those not needing changes.', '更新营业时间。', 'POST', '/api/v2/logistics/update_operating_hours', 1, 0),
(1301, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_update_self_collection_order_logistics', '更新自提订单物流状态', 'Use this api to update the order status for buyer to collect the orders directly from your pharmacy. This includes indicating that order is ready for collection, and that the order has been picked up by the buyer. You should call v2.logistics.get_order_detail or v2.logistics.get_package_detail first to get the package_number of such orders.', '更新自提订单物流状态。', 'POST', '/api/v2/logistics/update_self_collection_order_logistics', 1, 0),
(1302, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_update_shipping_order', '更新订单揽收安排', 'For pickup method only, use this api to update pickup address and pickup time for packages meet: 1) package''s fulfillment status is LOGISTICS_PICKUP_RETRY; or 2) package''s fulfillment status is ''LOGISTICS_REQUEST_CREATED'' and meets the Instant Order Reschedule Pickup conditions.', '更新订单揽收安排。', 'POST', '/api/v2/logistics/update_shipping_order', 1, 0),
(1303, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_update_tracking_status', '更新物流跟踪状态', 'Only available for Brazil sellers. This API is only available for orders/parcels which are fulfilled by BR Seller Logistics channel (logistics_channel_id: 90021), Samsung (logistics_channel_id: 90025) and BR Instant Delivery channel (logistics_channel_id: 90026). The logistics_status will become LOGISTICS_REQUEST_CREATED after arrange shipment, and can call this API to update to: LOGISTICS_PICKUP_DONE, LOGISTICS_DELIVERY_DONE, LOGISTICS_DELIVERY_FAILED.', '更新物流跟踪状态。', 'POST', '/api/v2/logistics/update_tracking_status', 1, 0),
(1304, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'logistics', '物流', 'v2_logistics_upload_serviceable_polygon', '上传可配送区域文件', 'Only available for Brazil sellers. Use this API to upload KML file for shop level serviceability setting for BR Entrega Turbo channel (Channel ID: 90026). Please note that multiple Outlet Shops under the same Mart Shop cannot have overlapping service areas.', '上传可配送区域文件。', 'POST', '/api/v2/logistics/upload_serviceable_polygon', 1, 0),
