(1307, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'firstmile', '首公里物流', 'v2_first_mile_generate_and_bind_first_mile_tracking_number', '生成并绑定快递配送首程运单号', 'Use this api to generate first mile tracking number for courier delivery method.', '生成并绑定快递配送首程运单号。', 'POST', '/api/v2/first_mile/generate_and_bind_first_mile_tracking_number', 1, 0),
