(1316, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'firstmile', '首公里物流', 'v2_first_mile_get_transit_warehouse_list', '查询中转仓库列表', 'Use this api to get transit warehouse list which is used for first mile tracking number generation for courier delivery method.', '查询中转仓库列表。', 'GET', '/api/v2/first_mile/get_transit_warehouse_list', 1, 0),
(1317, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'firstmile', '首公里物流', 'v2_first_mile_get_unbind_order_list', '查询未绑定首程运单的订单列表', 'Use this api to get unbind order list. It will only return orders unbound to first-mile that were created within the past 6 months.', '查询未绑定首程运单的订单列表。', 'GET', '/api/v2/first_mile/get_unbind_order_list', 1, 0),
