(1322, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'returns', '退货退款', 'v2_returns_cancel_dispute', '取消赔偿争议', 'Sellers can only cancel compensation disputes, not normal disputes. This means that sellers can only cancel disputes when the return_status is ACCEPTED and the compensation_status is COMPENSATION_REQUESTED.', '取消赔偿争议。', 'POST', '/api/v2/returns/cancel_dispute', 1, 0),
