(1330, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'returns', '退货退款', 'v2_returns_get_reverse_tracking_info', '查询退货逆向物流轨迹', 'Get reverse and post-return logistics information of return request. For Normal RR, return complete reverse logistics information, for In-transit RR and Return-on-the-Spot, only return latest reverse logistics status, without providing complete reverse logistics information. For seller_validation, only one segment of reverse (buyer to seller), use tracking_info, for warehouse_validation, two segment of reverse (buyer to warehouse and warehouse to seller), use post_return_logistics_tracking_info.', '查询退货逆向物流轨迹。', 'GET', '/api/v2/returns/get_reverse_tracking_info', 1, 0),
(1331, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'returns', '退货退款', 'v2_returns_get_shipping_carrier', '查询退货承运商', 'Use this API to get the list of shipping carriers and request parameters needed before calling v2.returns.upload_shipping_proof. Only for TW and BR returns with is_seller_arrange = true.', '查询退货承运商。', 'GET', '/api/v2/returns/get_shipping_carrier', 1, 0),
