(1334, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'returns', '退货退款', 'v2_returns_upload_proof', '上传退货争议证据', 'Support sellers to upload evidence, including text and pictures and videos converted into URLs.', '上传退货争议证据。', 'POST', '/api/v2/returns/upload_proof', 1, 0),
(1335, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'returns', '退货退款', 'v2_returns_upload_shipping_proof', '上传退货寄件凭证', 'Use this API to upload shipping proof (Only for TW and BR returns with is_seller_arrange = true). This is not to upload evidence for disputes.', '上传退货寄件凭证。', 'POST', '/api/v2/returns/upload_shipping_proof', 1, 0),
