(1350, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'fbs', 'FBS履约', 'v2_fbs_query_br_shop_invoice_error', '查询巴西FBS发票错误', 'This API handles failed invoice issuance for FBS-related processes, covering Inbound Requests, RTS Requests, Sales Orders, and Move Transfer Orders.', '查询巴西FBS发票错误。', 'GET', '/api/v2/fbs/query_br_shop_invoice_error', 1, 0),
