(1413, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_escrow_detail', '查询订单托管款明细', 'Use this API to fetch the accounting detail of order.', '查询订单托管款明细。', 'GET', '/api/v2/payment/get_escrow_detail', 1, 0),
(1414, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_escrow_list', '查询订单托管款列表', 'Use this API to fetch the accounting list of order.', '查询订单托管款列表。', 'GET', '/api/v2/payment/get_escrow_list', 1, 0),
(1415, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_income_detail', '查询收入明细', 'Retrieves detailed order-level income information across various income statuses for a specified time period. This API enables partners to display granular transaction-level income data consistent with Seller Center’s “Income Details” view, segmented by income status and payout stage. The API dynamically adapts data fields based on the seller’s shop type (Local or Cross Border) and the selected income status (e.g., Pending, To Release, Released).', '查询收入明细。', 'GET', '/api/v2/payment/get_income_detail', 1, 0),
(1416, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_income_overview', '查询收入概览', 'Retrieves a consolidated snapshot of the seller’s income amounts categorized by income status for a specified shop. This API provides a holistic overview similar to Seller Center’s “Income Overview” section, allowing external systems to reflect the same current payout view. Data is dynamically determined based on the shop type (Local or Cross Border) and the income status requested. Historical income results are not retrievable, providing consistent information as Seller Centre.', '查询收入概览。', 'GET', '/api/v2/payment/get_income_overview', 1, 0),
(1417, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_income_report', '查询收入报表', 'To query income report status and provide file link if the income report is ready to be downloaded.', '查询收入报表。', 'GET', '/api/v2/payment/get_income_report', 1, 0),
(1418, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_income_statement', '查询收入对账单', 'To query income statement status and provide file link if the income statement is ready to be downloaded.', '查询收入对账单。', 'GET', '/api/v2/payment/get_income_statement', 1, 0),
(1419, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_item_installment_status', '查询商品分期状态', 'Get item installment tenures.Only for TH、TW.', '查询商品分期状态。', 'POST', '/api/v2/payment/get_item_installment_status', 1, 0),
(1420, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_payment_method_list', '查询支付方式列表', 'Obtain payment method (no authentication required)', '查询支付方式列表。', 'GET', '/api/v2/payment/get_payment_method_list', 1, 0),
(1421, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_payout_detail', '查询跨境结算款明细', 'This API is applicable for Cross Border (CB) sellers only to get the shop''s payout data, such as the payout amount, currency, FX rate, the payout''s associated order income and adjustment records etc.', '查询跨境结算款明细。', 'GET', '/api/v2/payment/get_payout_detail', 1, 0),
(1422, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_payout_info', '查询跨境结算款信息', 'This is a new API which applicable for Cross Border (CB) sellers only to get the shop''s payout data, will be used for the original API v2.get_payout_details replacement, we provide data such as the payout amount, currency, FX rate, the payout''s associated order income and adjustment records etc.', '查询跨境结算款信息。', 'GET', '/api/v2/payment/get_payout_info', 1, 0),
