(1424, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_get_wallet_transaction_list', '查询钱包交易记录', 'Use this API to get the transaction records of wallet. Only applicable for local shops', '查询钱包交易记录。', 'GET', '/api/v2/payment/get_wallet_transaction_list', 1, 0),
