(1426, 'shopee-erp-api', 'Shopee ERP开放平台API', NULL, NULL, 'payment', '支付结算', 'v2_payment_set_shop_installment_status', '设置店铺分期状态', 'Sets the staging capability of shop level.', '设置店铺分期状态。', 'POST', '/api/v2/payment/set_shop_installment_status', 1, 0),
